mapper.select:
select * from cr_notice
where room_id = #{room_id}
order by status desc, release_time desc

select count(l.resource_id) as count,l.create_time,t.role_id as roleGroup from cr_notice l left join cr_task t on t.mission_id = l.mission_id where l.room_id = #{room_id} and l.user_id in
#{user}
and (l.action_code =${RELEASE} or l.action_code =${START_ANSWER}) group by l.create_time,t.role_id
